import React, { useEffect } from 'react';
import { FaPhone, FaMapMarkerAlt, FaClock, FaFacebook, FaInstagram, FaTwitter } from 'react-icons/fa';
import './footer.css';

const Footer = () => {
  useEffect(() => {
    const handleScroll = () => {
      const scrollTop = window.scrollY || document.documentElement.scrollTop;
      const windowHeight = window.innerHeight;
      const documentHeight = document.documentElement.scrollHeight;
      const threshold = 50; // pixels from bottom

      if (documentHeight - (scrollTop + windowHeight) < threshold) {
        document.body.classList.add('scrolled-to-bottom');
      } else {
        document.body.classList.remove('scrolled-to-bottom');
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <footer className="footer">
      <div className="footer-content">
        <div className="footer-section">
          <h3>Hotel Shyam</h3>
          <p>Authentic Indian cuisine since 1985</p>
        </div>

        <div className="footer-section">
          <h3>Contact</h3>
          <p><FaPhone /> +91 9876543210</p>
          <p><FaMapMarkerAlt /> 123 Food Street, Mumbai</p>
          <p><FaClock /> Open: 11AM - 11PM</p>
        </div>

        <div className="footer-section">
          <h3>Follow Us</h3>
        </div>
      </div>

      <div className="footer-bottom">
        <p>&copy; {new Date().getFullYear()} Hotel Shyam. All Rights Reserved.</p>
      </div>
    </footer>
  );
};

export default Footer;
